-- QB Season Builder: the private source ratings and the hand overrides table,
-- the schema half of the ratings pipeline (issue #75, sub-issue of #72). The
-- data half is 0124, generated by scripts/qb_ratings/build_ratings.py.
--
-- The finished values the game reads (qb_seasons, team_seasons) were created by
-- 0120. What arrives here is what they are *made from*, and it is kept where no
-- client can see it:
--
--   madden_ratings   the third-party talent ratings each finished value was
--                    blended from. The product never shows these numbers or
--                    their source: a client only ever gets the blended value,
--                    through qb_season_builder.state / pick / respin. Nothing
--                    in the exposed schemas reads this table, and none may.
--   rating_overrides hand corrections for a value the formulas get clearly
--                    wrong, and a function that applies them.
--
-- Both live in qb_season_builder_private, which is not in the exposed schema
-- list and grants no usage to anon or authenticated (0120): unreachable, not
-- merely unrouted. The revokes and RLS below are belt and braces on top of that,
-- the same as private.player_weeks (0007).
--
-- LICENSE POSTURE, so it is not lost: the Madden layer is an accepted-risk go,
-- not a permitted use (docs/games/qb_season_builder_madden_data.md). The rows
-- must stay private and derived-only, and the migration that loads them must
-- never reach a public repository. Setting the Madden weight to 0 in
-- scripts/qb_ratings/config.py and truncating this table is the way back.

-- ---------------------------------------------------------- the Madden ratings --

-- One row per player per edition. `edition` is the source's own season key: the
-- edition released in August of that season, so the one that rates season S is
-- edition S+1, with edition S as the fallback for a player it does not rate.
-- `player_id` is Pro Football Reference's id, the key every other pool here uses.
--
-- Only rows the pipeline actually read are loaded (rated quarterbacks and the
-- rostered players the Supporting Cast counts), and only observed ratings: an
-- attribute an edition does not have is null, never a guess. Attributes are not
-- range-checked above 99 because the source itself rates some of them above it.
create table qb_season_builder_private.madden_ratings (
  edition              smallint not null check (edition >= 2006),
  player_id            text     not null,
  position             text     not null,
  overall              smallint not null check (overall >= 0),
  throw_power          smallint check (throw_power >= 0),
  throw_accuracy_short smallint check (throw_accuracy_short >= 0),
  throw_accuracy_mid   smallint check (throw_accuracy_mid >= 0),
  throw_accuracy_deep  smallint check (throw_accuracy_deep >= 0),
  speed                smallint check (speed >= 0),
  acceleration         smallint check (acceleration >= 0),
  agility              smallint check (agility >= 0),
  awareness            smallint check (awareness >= 0),
  strength             smallint check (strength >= 0),
  toughness            smallint check (toughness >= 0),
  injury               smallint check (injury >= 0),
  stamina              smallint check (stamina >= 0),
  play_action          smallint check (play_action >= 0),
  throw_on_run         smallint check (throw_on_run >= 0),

  primary key (edition, player_id)
);

-- ---------------------------------------------------------- the hand overrides --

-- A value the formulas get clearly wrong, corrected by hand. `player_id` is ''
-- for a Supporting Cast override, which is keyed by team-season alone. `reason`
-- is for the next person who wonders why a number is what it is.
--
-- The pipeline reads the same overrides from scripts/qb_ratings/overrides.csv,
-- applies them to what it generates (so the build-time sanity checks see the
-- finished values), and loads them here. To correct a value in a database that
-- is already loaded without a rebuild, insert a row and call
-- apply_rating_overrides(), then add the same row to overrides.csv so a later
-- rebuild keeps it.
create table qb_season_builder_private.rating_overrides (
  franchise_code text     not null,
  season         smallint not null check (season between 2006 and 2025),
  player_id      text     not null default '',
  slot           text     not null check (slot in (
    'accuracy', 'arm_talent', 'mobility', 'iq', 'build', 'supporting_cast'
  )),
  value          smallint not null check (value between 0 and 99),
  reason         text     not null default '',

  primary key (franchise_code, season, player_id, slot),
  -- The cast has no quarterback; a quality always has one.
  check ((slot = 'supporting_cast') = (player_id = ''))
);

-- Overwrite every finished value that has an override. Returns how many were
-- applied. An override that matches no row is a typo in something a person
-- edits, and applying the rest quietly would look like a correction that had
-- been made, so it raises instead and nothing is changed.
create function qb_season_builder_private.apply_rating_overrides()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_slot    text;
  v_applied integer := 0;
  v_count   integer;
begin
  if exists (
    select 1 from qb_season_builder_private.rating_overrides o
     where case when o.slot = 'supporting_cast'
                then not exists (
                       select 1 from qb_season_builder_private.team_seasons t
                        where t.franchise_code = o.franchise_code and t.season = o.season)
                else not exists (
                       select 1 from qb_season_builder_private.qb_seasons q
                        where q.franchise_code = o.franchise_code and q.season = o.season
                          and q.player_id = o.player_id)
           end
  ) then
    raise exception 'override_matches_no_row' using errcode = 'P0002';
  end if;

  -- The five qualities share one shape; %I keeps the column name an identifier.
  foreach v_slot in array array['accuracy', 'arm_talent', 'mobility', 'iq', 'build'] loop
    execute format(
      'update qb_season_builder_private.qb_seasons q set %1$I = o.value
         from qb_season_builder_private.rating_overrides o
        where o.slot = %2$L and o.franchise_code = q.franchise_code
          and o.season = q.season and o.player_id = q.player_id',
      v_slot, v_slot);
    get diagnostics v_count = row_count;
    v_applied := v_applied + v_count;
  end loop;

  update qb_season_builder_private.team_seasons t
     set supporting_cast = o.value
    from qb_season_builder_private.rating_overrides o
   where o.slot = 'supporting_cast'
     and o.franchise_code = t.franchise_code and o.season = t.season;
  get diagnostics v_count = row_count;

  return v_applied + v_count;
end;
$$;

-- ---------------------------------------------------------------- privileges --

alter table qb_season_builder_private.madden_ratings   enable row level security;
alter table qb_season_builder_private.rating_overrides enable row level security;
revoke all on table qb_season_builder_private.madden_ratings   from public, anon, authenticated;
revoke all on table qb_season_builder_private.rating_overrides from public, anon, authenticated;

revoke all on function qb_season_builder_private.apply_rating_overrides()
  from public, anon, authenticated;
